Record fgeo (spz fa B0 cap : Z) : Prop := FGeo {
  fg_B0 : (0 < B0)%Z; fg_Bc : (B0 + cap < 2 ^ 63)%Z; fg_fa : (fa + 232 < 2 ^ 63)%Z;
  fg_sf : (spz <= fa)%Z; fg_sb : (spz <= B0)%Z; fg_d : (B0 + cap <= fa \/ fa + 232 <= B0)%Z; fg_c : (0 <= cap)%Z }.

Definition fst_at (m : word -> option byte) (fa B0 cap k lbf : Z) (ibuf : list byte)
    (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk) : Prop :=
  rw_cells rsegs m fa (fileC zflags rpos rend (Z_to_bv 64 (B0 + cap)) (Z_to_bv 64 (B0 + k)) wbase wfn bufp bsz mode lockv (Z_to_bv 64 lbf) cookie J)
  /\ u8arr rsegs m B0 ibuf /\ Z.of_nat (length ibuf) = cap /\ (0 <= k <= cap)%Z /\ (-2 ^ 31 <= lbf < 0)%Z.

