Lemma pfx_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo pl fa B0 cap k lbf : Z) (ibuf jB : list byte) (estr cg ns : word)
   (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> (lo + 64 <= bv_unsigned sp)%Z -> (bv_unsigned sp <= bv_unsigned s0 - 544)%Z ->
  (bv_unsigned s0 < 2 ^ 63)%Z -> (0xf8ac8 <= lo)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -496) [C8 (Z_to_bv 64 1); C8 estr; CB 8 jB; C8 (Z_to_bv 64 0); C8 cg; C8 ns; C8 (Z_to_bv 64 (68534 - pl));
                                             C8 (Z_to_bv 64 pl); C8 (Z_to_bv 64 fa)] ->
  fst_at m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J -> fgeo (bv_unsigned s0) fa B0 cap ->
  (0 <= pl <= 1)%Z -> (k + pl <= cap)%Z -> s5 = Z_to_bv 64 pl ->
  evt rsegs (fun ms' => exists ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3' t4' t5' t6') F
               (Z_to_bv 64 0xb1490) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (B0 + k, B0 + k + pl); (fa + 40, fa + 48)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (bv_unsigned s0 + -496) [C8 (Z_to_bv 64 1); C8 estr; CB 8 jB; C8 (Z_to_bv 64 0); C8 cg; C8 ns; C8 (Z_to_bv 64 (68534 - pl));
                                             C8 (Z_to_bv 64 pl); C8 (Z_to_bv 64 fa)]
      /\ fst_at m' fa B0 cap (k + pl) lbf (upd_bytes ibuf (Z.to_nat k) (pfxb pl)) rpos rend wbase wfn bufp bsz mode lockv cookie J)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
