Section FInt.
Variables (sp gp tp s0 : word) (F : bvmap 5 word) (lo B ia2 ir fa B0 cap lbf : Z).
Variables (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk).
Hypotheses (LO : (lo + 64 <= bv_unsigned sp)%Z) (SPS : (bv_unsigned sp <= bv_unsigned s0 - 1056)%Z) (HS0 : (bv_unsigned s0 < 2 ^ 63)%Z) (HLO : (0xf8ac8 <= lo)%Z)
           (G : fgeo (bv_unsigned s0) fa B0 cap).

Definition MAGIC10 : Z := 14757395258967641293.

(* [comment removed for export] *)
Lemma fint_limb : forall (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s6 s7 s9 t3 t4 t5 t6 : word) fc m (k id : Z) (ibuf dbuf : list byte) (ws : list word) (w : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) ->
  u32arr rsegs m B ws -> nth_error ws (Z.to_nat id) = Some w -> (0 <= ia2 <= id)%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  (bv_unsigned sp <= B)%Z -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z ->
  (bv_unsigned w < 1000000000)%Z ->
  rw_cells rsegs m (bv_unsigned s0 + -432) [C8 (Z_to_bv 64 fa)] -> rw_cells rsegs m (bv_unsigned s0 + -405) [CB 9 dbuf] ->
  fst_at m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J -> (k + 9 <= cap)%Z ->
  evt rsegs (fun ms' => exists (digs dbuf' : list byte) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      Forall isdigb digs /\ Z.of_nat (length digs) = (if (id =? ia2)%Z then Z.max 1 (ndig (bv_unsigned w)) else 9)%Z /\
      ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 MAGIC10) a0' a1' a2' a3' a4' a5' a6' a7' s2 (Z_to_bv 64 (B + 4 * id)) (Z_to_bv 64 (B + 4 * ia2))
                    (Z_to_bv 64 10) s6 s7 (Z_to_bv 64 (bv_unsigned s0 + -405)) s9 (Z_to_bv 64 48) (Z_to_bv 64 99) t3' t4' t5' t6') F
               (Z_to_bv 64 0xb14d4) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (B0 + k, B0 + k + 9); (fa + 40, fa + 48); (bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m'
      /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B ws
      /\ rw_cells rsegs m' (bv_unsigned s0 + -432) [C8 (Z_to_bv 64 fa)] /\ rw_cells rsegs m' (bv_unsigned s0 + -405) [CB 9 dbuf']
      /\ fst_at m' fa B0 cap (k + Z.of_nat (length digs)) lbf (upd_bytes ibuf (Z.to_nat k) digs) rpos rend wbase wfn bufp bsz mode lockv cookie J)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 MAGIC10) a0 a1 a2 a3 a4 a5 a6 a7 s2 (Z_to_bv 64 (B + 4 * id)) (Z_to_bv 64 (B + 4 * ia2))
             (Z_to_bv 64 10) s6 s7 (Z_to_bv 64 (bv_unsigned s0 + -405)) s9 (Z_to_bv 64 48) (Z_to_bv 64 99) t3 t4 t5 t6) F
        (Z_to_bv 64 0xb14dc) fc None m (seg_rom rsegs)).
