(* [comment removed for export] *)
Lemma fint_loop : forall (n : nat) (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2 s7 s9 t3 t4 t5 t6 : word) fc m (k id : Z) (ibuf dbuf : list byte) (ws : list word) (w : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) ->
  u32arr rsegs m B ws -> (0 <= ia2 <= id)%Z -> (id <= ir)%Z -> Z.of_nat n = (ir - id)%Z -> (ir < Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  (bv_unsigned sp <= B)%Z -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z ->
  (forall i x, (id <= i <= ir)%Z -> nth_error ws (Z.to_nat i) = Some x -> (bv_unsigned x < 1000000000)%Z) -> nth_error ws (Z.to_nat id) = Some w ->
  rw_cells rsegs m (bv_unsigned s0 + -432) [C8 (Z_to_bv 64 fa)] -> rw_cells rsegs m (bv_unsigned s0 + -405) [CB 9 dbuf] ->
  fst_at m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J -> (k + 9 * (Z.of_nat n + 1) <= cap)%Z ->
  evt rsegs (fun ms' => exists (digs dbuf' : list byte) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' m',
      Forall isdigb digs /\ Z.of_nat (length digs) = ((if (id =? ia2)%Z then Z.max 1 (ndig (bv_unsigned w)) else 9) + 9 * (ir - id))%Z /\
      ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 MAGIC10) a0' a1' a2' a3' a4' a5' a6' a7' s2 (Z_to_bv 64 (B + 4 * (ir + 1))) (Z_to_bv 64 (B + 4 * ia2))
                    (Z_to_bv 64 10) (Z_to_bv 64 (B + 4 * ir)) s7 (Z_to_bv 64 (bv_unsigned s0 + -405)) s9 (Z_to_bv 64 48) (Z_to_bv 64 99) t3' t4' t5' t6') F
               (Z_to_bv 64 0xb1750) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (B0 + k, B0 + k + 9 * (Z.of_nat n + 1)); (fa + 40, fa + 48); (bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m'
      /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B ws
      /\ rw_cells rsegs m' (bv_unsigned s0 + -432) [C8 (Z_to_bv 64 fa)] /\ rw_cells rsegs m' (bv_unsigned s0 + -405) [CB 9 dbuf']
      /\ fst_at m' fa B0 cap (k + Z.of_nat (length digs)) lbf (upd_bytes ibuf (Z.to_nat k) digs) rpos rend wbase wfn bufp bsz mode lockv cookie J)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 MAGIC10) a0 a1 a2 a3 a4 a5 a6 a7 s2 (Z_to_bv 64 (B + 4 * id)) (Z_to_bv 64 (B + 4 * ia2))
             (Z_to_bv 64 10) (Z_to_bv 64 (B + 4 * ir)) s7 (Z_to_bv 64 (bv_unsigned s0 + -405)) s9 (Z_to_bv 64 48) (Z_to_bv 64 99) t3 t4 t5 t6) F
