Ltac fix_sb1 :=
  lazymatch goal with
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ (Z_to_le_bytes 1 ?c)) _) => change (Z_to_le_bytes 1 c) with [Z_to_bv 8 c]
  | |- evt _ _ (MS _ _ _ _ _ (write_to_mem _ _ (le1 (Z_to_bv 64 ?v))) _) =>
    change (le1 (Z_to_bv 64 v)) with [Z_to_bv 8 (bv_unsigned (Z_to_bv 64 v))]; rewrite (unsigned_small64 v) by lia
  end.

(* [comment removed for export] *)
Lemma fdig_loop : forall (n : nat) (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s7 s9 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (j x : Z) (bs : list byte),
  mem_inv rsegs m -> u8arr rsegs m (bv_unsigned s0 + -405) bs -> length bs = 9%nat -> (bv_unsigned s0 < 2 ^ 63)%Z -> (1024 <= bv_unsigned s0)%Z ->
  Z.of_nat n = j -> (2 <= j <= 9)%Z -> (10 <= x < 10 ^ j)%Z -> digs_from bs j ->
  a0 = Z_to_bv 64 x -> a2 = Z_to_bv 64 (bv_unsigned s0 + -405 + j) ->
  evt rsegs (fun ms' => exists (j' : Z) (bs' : list byte) a0' a2' a3' a4' m',
      (0 <= j' < j)%Z /\ digs_from bs' j' /\ length bs' = 9%nat /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) a0' (Z_to_bv 64 (bv_unsigned s0 + -405 + j')) a2' a3' a4' a5 a6 a7 s2 s3 (Z_to_bv 64 10)
                    (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) s7 (Z_to_bv 64 MAGIC10) s9 (Z_to_bv 64 9) s11 t3 t4 t5 t6) F
               (Z_to_bv 64 0xb17f0) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ u8arr rsegs m' (bv_unsigned s0 + -405) bs')
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 (Z_to_bv 64 10)
             (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) s7 (Z_to_bv 64 MAGIC10) s9 (Z_to_bv 64 9) s11 t3 t4 t5 t6) F
        (Z_to_bv 64 0xb17b4) fc None m (seg_rom rsegs)).
Proof.
