Lemma fmt9f_walk : forall (ra sp gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s7 s9 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (B id : Z) (ws : list word) (w : word) (dbuf : list byte),
  mem_inv rsegs m -> u32arr rsegs m B ws -> nth_error ws (Z.to_nat id) = Some w -> (0 <= id)%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  (bv_unsigned w < 1000000000)%Z -> s3 = Z_to_bv 64 (B + 4 * id) ->
  u8arr rsegs m (bv_unsigned s0 + -405) dbuf -> length dbuf = 9%nat ->
  (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z -> (bv_unsigned s0 < 2 ^ 63)%Z -> (1024 <= bv_unsigned s0)%Z ->
  evt rsegs (fun ms' => exists (dg : list byte) a1' a2' a3' a4' m',
      Forall isdigb dg /\ length dg = 9%nat /\
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) (Z_to_bv 64 (bv_unsigned s0 + -405)) a1' a2' a3' a4' a5 a6 a7 s2 s3 (Z_to_bv 64 10)
