(* [comment removed for export] *)
Lemma pad_dead_walk : forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
   (F : bvmap 5 word) fc m (lo w l : Z) (G : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) -> (lo + 304 <= bv_unsigned sp)%Z -> (0xf8ac8 <= lo)%Z -> (bv_unsigned ra mod 2 = 0)%Z ->
  ro_cells rsegs m 0xc5ab8 [C8 (Z_to_bv 64 0xf8ac0)] -> ro_cells rsegs m 0xf8ac0 [C8 G] ->
  a2 = Z_to_bv 64 w -> a3 = Z_to_bv 64 l -> (-2 ^ 31 <= w <= l)%Z -> (l < 2 ^ 31)%Z ->
  evt rsegs (fun ms' => exists a0' a1' m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0' a1' a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
               (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 304, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp))
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F
