Section FFrac.
Variables (sp gp tp s0 : word) (F : bvmap 5 word) (lo B iz fa B0 cap lbf : Z).
Variables (rpos rend wbase wfn bufp bsz mode lockv cookie : word) (J : fjunk).
Hypotheses (LO : (lo + 64 <= bv_unsigned sp)%Z) (SPS : (bv_unsigned sp <= bv_unsigned s0 - 1056)%Z) (HS0 : (bv_unsigned s0 < 2 ^ 63)%Z) (HLO : (0xf8ac8 <= lo)%Z)
           (G : fgeo (bv_unsigned s0) fa B0 cap).

(* [comment removed for export] *)
Lemma ffrac_loop : forall (n : nat) (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s9 t3 t4 t5 t6 : word) fc m (k id p : Z) (ibuf dbuf : list byte) (ws : list word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) ->
  u32arr rsegs m B ws -> (0 <= id < iz)%Z -> Z.of_nat n = (iz - id)%Z -> (iz <= Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
  (bv_unsigned sp <= B)%Z -> (B + 4 * Z.of_nat (length ws) <= bv_unsigned s0 - 544)%Z ->
  limbs_ok ws id iz -> (1 <= p <= 9 * (iz - id))%Z -> (p < 2 ^ 20)%Z ->
  u8arr rsegs m (bv_unsigned s0 + -405) dbuf -> length dbuf = 9%nat ->
  fst_at m fa B0 cap k lbf ibuf rpos rend wbase wfn bufp bsz mode lockv cookie J -> (k + p <= cap)%Z ->
  evt rsegs (fun ms' => exists (digs dbuf' : list byte) (pf idf : Z) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s9' t3' t4' t5' t6' m',
      Forall isdigb digs /\ Z.of_nat (length digs) = p /\ (-9 < pf <= 0)%Z /\
      ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 99) a0' a1' a2' a3' a4' a5' a6' a7' (Z_to_bv 64 pf) (Z_to_bv 64 (B + 4 * idf)) (Z_to_bv 64 10)
                    (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) (Z_to_bv 64 (B + 4 * iz)) (Z_to_bv 64 MAGIC10) s9' (Z_to_bv 64 9) (Z_to_bv 64 fa) t3' t4' t5' t6') F
               (Z_to_bv 64 0xb1850) fc None m' (seg_rom rsegs)
      /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (B0 + k, B0 + k + p); (fa + 40, fa + 48); (bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m'
      /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B ws
      /\ u8arr rsegs m' (bv_unsigned s0 + -405) dbuf' /\ length dbuf' = 9%nat
      /\ fst_at m' fa B0 cap (k + p) lbf (upd_bytes ibuf (Z.to_nat k) digs) rpos rend wbase wfn bufp bsz mode lockv cookie J)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 99) a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 p) (Z_to_bv 64 (B + 4 * id)) (Z_to_bv 64 10)
             (Z_to_bv 64 (bv_unsigned s0 + -405)) (Z_to_bv 64 48) (Z_to_bv 64 (B + 4 * iz)) (Z_to_bv 64 MAGIC10) s9 (Z_to_bv 64 9) (Z_to_bv 64 fa) t3 t4 t5 t6) F
        (Z_to_bv 64 0xb17a8) fc None m (seg_rom rsegs)).
Proof.
