Variable c6 : word.
Definition FR4 : list cell := [C8 (Z_to_bv 64 0); C8 c6; C8 (Z_to_bv 64 69319); C8 (Z_to_bv 64 fa)].
Definition eout (d0 : byte) (ds : list byte) (p : Z) : list byte := d0 :: (if (0 <? p)%Z then Z_to_bv 8 46 :: ds else []).

Definition epost1 (m : word -> option byte) (k p : Z) (ibuf : list byte) (ws : list word) (fc : bv 32) : machine_state -> Prop :=
  fun ms' => exists (d0 : byte) (ds dbuf' : list byte) (pf idf : Z) ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s5' s11' t3' t4' t5' t6' m',
      isdigb d0 /\ Forall isdigb ds /\ Z.of_nat (length ds) = p /\ (-9 <= pf <= 0)%Z /\
      ms' = est ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s5' s11' t3' t4' t5' t6' fc m' 0xb1708 pf idf
      /\ munch [(bv_unsigned sp - 64, bv_unsigned sp); (B0 + k, B0 + k + p + 2); (fa + 40, fa + 48); (bv_unsigned s0 + -405, bv_unsigned s0 + -396)]%Z m m'
      /\ wmono rsegs m m' /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp) /\ u32arr rsegs m' B ws
      /\ rw_cells rsegs m' (bv_unsigned s0 + -456) FR4 /\ rw_cells rsegs m' (bv_unsigned s0 + -405) [CB 9 dbuf']
      /\ fst_at m' fa B0 cap (k + Z.of_nat (length (eout d0 ds p))) lbf (upd_bytes ibuf (Z.to_nat k) (eout d0 ds p)) rpos rend wbase wfn bufp bsz mode lockv cookie J.

(* [comment removed for export] *)
Lemma efirst_walk : forall (ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s5 s11 t3 t4 t5 t6 : word) fc m (k p : Z) (ibuf dbuf : list byte) (ws : list word) (w : word),
  mem_inv rsegs m -> stk rsegs m lo (bv_unsigned sp) ->
  u32arr rsegs m B ws -> (0 <= ia < iz)%Z -> (iz <= Z.of_nat (length ws))%Z -> (B + 4 * Z.of_nat (length ws) < 2 ^ 63)%Z ->
