From Stdlib Require ZArith List Lia Bool. From stdpp.bitvector Require definitions. From LinuxProcessSemantics.LinuxProcessSem Require BvBase. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102.
Module WdGnumB.
From OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib Require BvWfKernel.
(* [comment removed for export] *)
(* [comment removed for export] *)
From Stdlib Require Import ZArith List Lia Bool.
From stdpp.bitvector Require Import definitions.
From LinuxProcessSemantics.LinuxProcessSem Require Import BvBase.
Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102. Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0111. Import OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102.WdLibc OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0111.WdWkFmtE.
Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102. Import OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102.WdGnum OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0134.WdWkFmtF OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0134.WdWkFmtH.
Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Definition zs (bs : list byte) : list Z := map bv_unsigned bs.

Lemma alldig_zs ds : Forall isdigb ds -> alldig (zs ds).
Proof. intros H. unfold alldig, zs. apply Forall_map. eapply Forall_impl; [|exact H]. intros b [H1 H2]. unfold WDL.isdig. apply andb_true_intro. split; apply Z.leb_le; lia. Qed.
Lemma zs_app a b : zs (a ++ b) = zs a ++ zs b. Proof. apply map_app. Qed.
Lemma zs_len a : length (zs a) = length a. Proof. apply length_map. Qed.
Lemma zs_pfxb pl : zs (pfxb pl) = if (pl =? 1) then [45] else [].
Proof. unfold pfxb. destruct (pl =? 1); reflexivity. Qed.
Lemma zs_range bs : Forall (fun c => 0 <= c < 256) (zs bs).
Proof. unfold zs. apply Forall_map. apply Forall_forall. intros b _. pose proof (bv_unsigned_in_range _ b) as R. change (bv_modulus 8) with 256 in R. exact R. Qed.

(* [comment removed for export] *)
Lemma gnum_fstyle pl d1 d2 p2 : Forall isdigb d1 -> (1 <= length d1)%nat -> Forall isdigb d2 -> Z.of_nat (length d2) = p2 ->
  WDL.gnum (zs (pfxb pl ++ d1 ++ (if (0 <? p2) then Z_to_bv 8 46 :: d2 else []))) = true.
Proof.
  intros H1 L1 H2 L2. rewrite !zs_app, zs_pfxb.
  replace (zs (if 0 <? p2 then Z_to_bv 8 46 :: d2 else [])) with ((if 0 <? p2 then 46 :: zs d2 else []) ++ []) by (destruct (0 <? p2); cbn; rewrite ?app_nil_r; reflexivity).
  apply gnum_body.
  - apply alldig_zs. exact H1.
  - rewrite zs_len. exact L1.
  - apply alldig_zs. exact H2.
  - intros E. apply Z.ltb_lt in E. rewrite zs_len. lia.
  - reflexivity.
  - exact I.
  - exact I.
Qed.

(* [comment removed for export] *)
Lemma gnum_estyle pl d0 ds p2 sg dse : isdigb d0 -> Forall isdigb ds -> Z.of_nat (length ds) = p2 -> (sg = 43 \/ sg = 45) -> Forall isdigb dse -> (2 <= length dse)%nat ->
  WDL.gnum (zs (pfxb pl ++ eout d0 ds p2 ++ Z_to_bv 8 101 :: Z_to_bv 8 sg :: dse)) = true.
Proof.
  intros H0 H1 L1 Hs H2 L2. rewrite !zs_app, zs_pfxb. unfold eout.
  replace (zs (d0 :: (if 0 <? p2 then Z_to_bv 8 46 :: ds else []))) with (zs [d0] ++ (if 0 <? p2 then 46 :: zs ds else [])) by (destruct (0 <? p2); reflexivity).
  rewrite <- app_assoc.
  replace (zs (Z_to_bv 8 101 :: Z_to_bv 8 sg :: dse)) with (101 :: sg :: zs dse) by (destruct Hs as [-> | ->]; reflexivity).
  apply gnum_body.
  - apply alldig_zs. constructor; [exact H0 | constructor].
  - cbn. lia.
  - apply alldig_zs. exact H1.
  - intros E. apply Z.ltb_lt in E. rewrite zs_len. lia.
  - apply gnum_tail_e; [exact Hs | apply alldig_zs; exact H2 | rewrite zs_len; exact L2].
  - reflexivity.
  - discriminate.
Qed.

End WdGnumB.
Module WdStGnum.
From OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib Require BvWfKernel.
(* [comment removed for export] *)
(* [comment removed for export] *)
From Stdlib Require Import ZArith List Lia Bool.
From stdpp.bitvector Require Import definitions.
Require OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102. Import OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102.WdLibc OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0102.WdGnum OSSVerify.Proofs.jsoncons.fuzz_msgpack_encoder.lib.Mh_0134.WdGnumB.
Import ListNotations. Local Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Lemma digits_split (r : list Z) : exists ds rest, r = ds ++ rest /\ alldig ds /\ nodig_head rest /\ WDL.skip_digits r = rest /\ WDL.ndig r = length ds.
Proof.
  induction r as [|c r IH].
  - exists [], []. repeat split; try reflexivity. constructor.
  - destruct (WDL.isdig c) eqn:E.
    + destruct IH as (ds & rest & -> & Hd & Hn & Hs & Hl). exists (c :: ds), rest.
      split; [reflexivity|]. split; [constructor; assumption|]. split; [exact Hn|].
      split; [cbn [WDL.skip_digits app]; rewrite E; exact Hs|].
      unfold WDL.ndig in *. cbn [WDL.skip_digits app]. rewrite E. rewrite Hs in *. cbn [length]. rewrite length_app in *. lia.
    + exists [], (c :: r). split; [reflexivity|]. split; [constructor|]. split; [exact E|].
      split; [cbn [WDL.skip_digits]; rewrite E; reflexivity|]. unfold WDL.ndig. cbn [WDL.skip_digits]. rewrite E. cbn [length]. lia.
Qed.

Definition gshape (bs : list Z) (neg : bool) (d1 : list Z) (dot : bool) (d2 : list Z) (ex : bool) (sg : Z) (de : list Z) : Prop :=
  bs = (if neg then [45] else []) ++ d1 ++ (if dot then 46 :: d2 else []) ++ (if ex then 101 :: sg :: de else [])
  /\ alldig d1 /\ (1 <= length d1)%nat /\ alldig d2 /\ (dot = true -> (1 <= length d2)%nat)
  /\ (ex = true -> (sg = 43 \/ sg = 45) /\ alldig de /\ (2 <= length de)%nat).

Lemma gnum_tail_inv T : WDL.gnum_tail T = true -> T = [] \/ exists sg de, T = 101 :: sg :: de /\ (sg = 43 \/ sg = 45) /\ alldig de /\ (2 <= length de)%nat.
Proof.
  destruct T as [|c r]; [left; reflexivity|]. cbn [WDL.gnum_tail]. intros H. apply andb_prop in H. destruct H as [Hc He]. apply Z.eqb_eq in Hc. subst c.
  right. unfold WDL.gnum_exp in He. destruct r as [|sg de]; [discriminate|].
  apply andb_prop in He. destruct He as [He H0]. apply andb_prop in He. destruct He as [Hs Hn].
  exists sg, de. split; [reflexivity|].
  split. { apply orb_prop in Hs. destruct Hs as [Hs|Hs]; apply Z.eqb_eq in Hs; [left | right]; exact Hs. }
  destruct (digits_split de) as (ds & rest & E & Hd & Hnd & Hsk & Hl).
  rewrite Hsk in H0. apply Nat.eqb_eq in H0. destruct rest; [|discriminate]. rewrite app_nil_r in E. subst ds.
  split; [exact Hd|]. rewrite Hl in Hn. apply Nat.leb_le in Hn. exact Hn.
Qed.

Theorem gnum_inv (bs : list Z) : WDL.gnum bs = true -> exists neg d1 dot d2 ex sg de, gshape bs neg d1 dot d2 ex sg de.
Proof.
  unfold WDL.gnum. cbv zeta. intros H. apply andb_prop in H. destruct H as [Hn Hf].
  set (bs1 := match bs with c :: r => if c =? 45 then r else bs | [] => bs end) in *.
  assert (Eb : exists neg : bool, bs = (if neg then [45] else @nil Z) ++ bs1).
  { subst bs1. destruct bs as [|c r]; [exists false; reflexivity|]. destruct (Z.eqb_spec c 45) as [-> | N]; [exists true | exists false]; reflexivity. }
  destruct Eb as (neg & Eb).
  destruct (digits_split bs1) as (d1 & rest & E1 & Hd1 & Hnd1 & Hs1 & Hl1).
  rewrite Hl1 in Hn. apply Nat.leb_le in Hn. rewrite Hs1 in Hf.
  assert (TAIL : forall T, WDL.gnum_tail T = true -> exists (ex : bool) (sg : Z) (de : list Z), T = (if ex then 101 :: sg :: de else @nil Z) /\ (ex = true -> (sg = 43 \/ sg = 45) /\ alldig de /\ (2 <= length de)%nat)).
  { intros T HT. destruct (gnum_tail_inv T HT) as [-> | (sg & de & -> & Hs & Hd & Hl)].
    - exists false, 0, []. split; [reflexivity | intros; discriminate].
    - exists true, sg, de. split; [reflexivity | intros _; repeat split; assumption]. }
  destruct rest as [|c r].
  - exists neg, d1, false, [], false, 0, []. unfold gshape. rewrite Eb, E1. cbn [app]. rewrite !app_nil_r.
    split; [reflexivity|]. split; [exact Hd1|]. split; [exact Hn|]. split; [constructor|]. split; intros; discriminate.
  - cbn [WDL.gnum_frac] in Hf. destruct (Z.eqb_spec c 46) as [-> | N46].
    + apply andb_prop in Hf. destruct Hf as [Hn2 Ht].
      destruct (digits_split r) as (d2 & rest2 & E2 & Hd2 & Hnd2 & Hs2 & Hl2).
      rewrite Hl2 in Hn2. apply Nat.leb_le in Hn2. rewrite Hs2 in Ht.
      destruct (TAIL rest2 Ht) as (ex & sg & de & -> & Hex).
      exists neg, d1, true, d2, ex, sg, de. unfold gshape. rewrite Eb, E1, E2. cbn [app].
      split; [reflexivity|]. split; [exact Hd1|]. split; [exact Hn|]. split; [exact Hd2|]. split; [intros _; exact Hn2 | exact Hex].
    + destruct (TAIL (c :: r) Hf) as (ex & sg & de & ET & Hex).
      exists neg, d1, false, [], ex, sg, de. unfold gshape. rewrite Eb, E1, ET. cbn [app].
      split; [reflexivity|]. split; [exact Hd1|]. split; [exact Hn|]. split; [constructor|]. split; [intros; discriminate | exact Hex].
Qed.

End WdStGnum.
